  // FONT_MISSING check treats them as system-equivalent.
  const runtimePrefixes = (ver?.runtimeFontPrefixes ?? []).map((p) => p.toLowerCase()).filter(Boolean);
  const isGeneric = (f) =>
    GENERIC_FAMILIES.has(f) ||
