        if (bad.length) fail(`[BUNDLE_EXPORT] ${bad.length}/${headerMeta.components.length} not a component on window.${headerMeta.namespace}: ${bad.slice(0, 8).join(', ')}${bad.length > 8 ? ', …' : ''}`);
