  // `.+` (not `[^;]+`) so object-param types with inner semicolons still match.
  for (const m of body.matchAll(/^ {2}([a-zA-Z_$][\w$]*)(\??)\s*:\s*(.+);$/gm)) {
    const [, prop, q, t] = m;
